def process_downloaded_files_scoped(
    downloads_dir: Path,
    report_type: str,
    target_date: str,
    postgres_hook,
    minio_bucket: str = 'faz-consulting-app',
    min_frac: float = 0.5,
    unlink_after_success: bool = False,
) -> Dict[str, Any]:
    """Pipeline NOVO por arquivo (B1+B2): MinIO + transform + swap escopado +
    rebuild da _latest. Zero arquivos = ESTADO (pending_unavailable), não falha.

    Retorna por arquivo: conta (do nome account_X_*), linhas, introducers
    trocados/preservados — é o que o ledger usa para confirmar downloads.
    """
    result: Dict[str, Any] = {
        'report_type': report_type,
        'target_date': target_date,
        'files': [],
        'any_loaded': False,
        'success': True,
        'alerts': [],
        'error': None,
    }
    try:
        files = find_downloaded_files(downloads_dir, report_type, target_date)
    except Exception as e:
        result['success'] = False
        result['error'] = f"falha ao listar arquivos: {e}"
        return result

    if not files:
        logger.info(f"[B1] nenhum arquivo de {report_type} para {target_date} (estado, não falha)")
        return result

    try:
        baseline = fetch_introducer_baseline(postgres_hook, report_type)
    except Exception as e:
        logger.warning(f"[B1] baseline indisponível ({e}); seguindo sem gate de parcialidade")
        baseline = {}

    for file_path in sorted(files):
        entry: Dict[str, Any] = {
            'file': file_path.name,
            'account': account_letter_from_filename(file_path.name),
            'success': False, 'rows_loaded': 0,
        }
        try:
            upload_files_to_minio([file_path], report_type, target_date, minio_bucket)
            _raw, transformed, _ref = process_single_file(file_path, report_type)
            up = upload_file_scoped(
                transformed, report_type, postgres_hook,
                min_frac=min_frac, baseline=baseline,
            )
            entry.update(up)
            result['alerts'].extend(up.get('alerts') or [])
            if up['success'] and up['rows_loaded'] > 0:
                result['any_loaded'] = True
                if unlink_after_success:
                    try:  # evita reprocessar o mesmo arquivo no próximo ciclo do loop
                        file_path.unlink()
                    except OSError as ue:
                        logger.warning(f"[B1] não removeu {file_path.name} pós-load: {ue}")
            if not up['success']:
                result['success'] = False
        except Exception as e:
            entry['error'] = str(e)
            result['success'] = False
            logger.error(f"[B1] erro processando {file_path.name}: {e}")
        result['files'].append(entry)

    if result['any_loaded']:
        rebuild_latest_from_main(postgres_hook, report_type)

    return result
